import{_ as a,o,c as r,a6 as s}from"./chunks/framework.CKIbuWFA.js";const f=JSON.parse('{"title":"Respaldar y restaurar el trabajo local","description":"","frontmatter":{"title":"Respaldar y restaurar el trabajo local","docId":"user.preferences.backups","translationKey":"user.preferences.backups","locale":"es","audience":"user","featureStatus":"available","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"b2ae789f9c15df21b415b5bc006404dffd60430f193fdaba8cd94931e750eedc","translationRevision":"cd221075da1efc3cf1ae5f670290ebf4634a3daf64be7ae081b0655705f7933c","order":20},"headers":[],"relativePath":"es/user/preferences/backups.md","filePath":"es/user/preferences/backups.md","lastUpdated":1794611623000}'),i={name:"es/user/preferences/backups.md"};function t(l,e,n,c,d,p){return o(),r("div",null,[...e[0]||(e[0]=[s('<h1 id="back-up-and-restore-local-work" tabindex="-1">Respaldar y restaurar el trabajo local <a class="header-anchor" href="#back-up-and-restore-local-work" aria-label="Permalink to &quot;Respaldar y restaurar el trabajo local {#back-up-and-restore-local-work}&quot;">​</a></h1><h2 id="goal-and-prerequisites" tabindex="-1">Objetivo y requisitos <a class="header-anchor" href="#goal-and-prerequisites" aria-label="Permalink to &quot;Objetivo y requisitos {#goal-and-prerequisites}&quot;">​</a></h2><p>Conserva una configuración funcional antes de actualizar, reiniciar datos o cambiar de equipo. Necesitas almacenamiento bajo tu control y tiempo para cerrar TikTools correctamente. La interfaz actual no incluye un botón universal para respaldarlo todo; combina exportaciones específicas con una copia de datos hecha con la aplicación cerrada.</p><h2 id="export-reusable-definitions" tabindex="-1">Exportar definiciones reutilizables <a class="header-anchor" href="#export-reusable-definitions" aria-label="Permalink to &quot;Exportar definiciones reutilizables {#export-reusable-definitions}&quot;">​</a></h2><ol><li>En <strong>Automations</strong>, selecciona el perfil deseado y expórtalo a un archivo <code>.tikprofile.json</code>. Incluye versión y fecha en su nombre.</li><li>Para una plantilla individual, usa la descarga/exportación del diálogo cuando esté disponible y guarda <code>.tiktemplate.json</code>.</li><li>Inspecciona el archivo antes de compartirlo. Las plantillas pueden contener destinos y valores de configuración. Exportar un perfil no copia saldos, estadísticas, variables de ejecución, medios ni credenciales de cuenta.</li></ol><h2 id="copy-the-local-data" tabindex="-1">Copiar los datos locales <a class="header-anchor" href="#copy-the-local-data" aria-label="Permalink to &quot;Copiar los datos locales {#copy-the-local-data}&quot;">​</a></h2><ol><li>Detén la actividad LIVE y el servicio de colaboración y sal de TikTools normalmente. Espera a que el host termine de escribir.</li><li>Localiza la raíz activa. Los valores predeterminados son <code>%LOCALAPPDATA%\\TikTools</code> en Windows y <code>~/.local/share/TikTools</code> en Linux, o <code>TikTools</code> dentro de <code>XDG_DATA_HOME</code> si está configurado. <code>TIKTOOLS_HOME</code> y las rutas particulares pueden cambiar estas ubicaciones.</li><li>Copia la raíz y los directorios de datos, plugins, datos de plugins y almacén de plugins que se hayan configurado por separado a una carpeta fechada. Copia el directorio completo de bases cerradas, incluidos los archivos auxiliares SQLite presentes, en lugar de seleccionar solo un <code>.db</code>.</li><li>Conserva aparte los archivos de audio referenciados: las acciones guardan rutas, no los bytes del sonido. Anota versión y ubicaciones personalizadas junto a la copia.</li><li>Protege el respaldo porque la configuración puede incluir valores privados. La autenticación de Cloud permanece en el almacén del sistema operativo y no se transporta mediante esta copia.</li></ol><h2 id="restore-and-verify" tabindex="-1">Restaurar y verificar <a class="header-anchor" href="#restore-and-verify" aria-label="Permalink to &quot;Restaurar y verificar {#restore-and-verify}&quot;">​</a></h2><p>Con TikTools cerrado, conserva la carpeta actual como recuperación separada. Restaura los archivos a las rutas previstas e inicia una versión compatible. Inspecciona perfil, saldos, variables y medios antes de conectar. Para definiciones portátiles, importa el perfil o plantilla desde Automations; permanecen desactivadas hasta su activación explícita.</p><h2 id="expected-result-status-and-recovery" tabindex="-1">Resultado esperado, estado y recuperación <a class="header-anchor" href="#expected-result-status-and-recovery" aria-label="Permalink to &quot;Resultado esperado, estado y recuperación {#expected-result-status-and-recovery}&quot;">​</a></h2><p>Las copias con la aplicación cerrada y las superficies indicadas están disponibles, sin garantía universal entre versiones. Changes de Cloud no es un respaldo completo. Si la versión rechaza los datos, detente y recupera la copia preservada; reinstalar un ejecutable anterior no revierte una migración. Consulta <a href="./../updates.html">actualizaciones</a> y <a href="./troubleshooting.html">solución de problemas</a>.</p><h2 id="operational-details" tabindex="-1">Detalles de operación <a class="header-anchor" href="#operational-details" aria-label="Permalink to &quot;Detalles de operación {#operational-details}&quot;">​</a></h2><p>Los overrides individuales prevalecen sobre <code>TIKTOOLS_HOME</code>: <code>TIKTOOLS_DATA_DIR</code> contiene bases; <code>TIKTOOLS_PLUGINS_DIR</code>, paquetes; <code>TIKTOOLS_PLUGIN_DATA_DIR</code>, estado de plugins; <code>TIKTOOLS_PLUGIN_STORE_DIR</code>, almacén de paquetes. <code>TIKTOOLS_LOG_DIR</code> y <code>TIKTOOLS_TEMP_DIR</code> eligen logs y temporales. Los valores relativos parten del directorio de lanzamiento. Antes de copiar, consulta rutas efectivas con <code>tiktools api call system.info --json</code> y anota overrides heredados; copia datos/paquetes/estado con el host detenido, incluidos WAL/SHM existentes. Los logs son evidencia de soporte, no sustituyen las bases.</p><p><code>system.info</code> informa home/dataDir efectivos; resuelve los demás directorios con el entorno real de lanzamiento del host, no otra terminal. Usa <code>system.health</code> para ready/pendientes analíticos y contadores de ingreso LIVE.</p>',14)])])}const b=a(i,[["render",t]]);export{f as __pageData,b as default};
